const comments=[
 {id:1,client:'lka',clientName:'LKA Fraser',person:'Emily R.',initials:'ER',comment:'Do you still have spaces available for the 6–8 age group next Saturday?',ad:'Kids Cooking Classes — Fall',format:'Video · Meta Ads',sentiment:'question',priority:'high',time:'4 min ago',unanswered:true,suggestion:'Hi Emily! Thanks for reaching out. Availability changes quickly, but you can see the latest spaces for ages 6–8 through our registration page. If you share the class date you are considering, we can also help point you in the right direction.'},
 {id:2,client:'enotecca',clientName:'Le Vieux Pin',person:'Marc D.',initials:'MD',comment:'Est-ce que vous livrez au Québec? Et combien coûte la livraison?',ad:'French Wine Society',format:'Carousel · Meta Ads',sentiment:'question',priority:'high',time:'11 min ago',unanswered:true,suggestion:'Bonjour Marc! Oui, nous livrons au Québec. Les frais et options de livraison s’affichent au moment de passer la commande selon votre adresse. N’hésitez pas à nous écrire si vous souhaitez de l’aide avec une commande.'},
 {id:3,client:'thrivebox',clientName:'ThriveBox',person:'Jenna P.',initials:'JP',comment:'My daughter would absolutely love this! Is the Winter box suitable for a 9-year-old?',ad:'Winter 2026 — UGC Unboxing',format:'Video · Instagram',sentiment:'positive',priority:'medium',time:'19 min ago',unanswered:true,suggestion:'Thank you, Jenna! The Winter 2026 ThriveBox is designed to create an engaging hands-on experience for students. We’d be happy to help confirm whether it is the right fit for your daughter—please send us a message with any questions about the activities included.'},
 {id:4,client:'enotecca',clientName:'LaStella',person:'Oliver S.',initials:'OS',comment:'I clicked through but I cannot tell what is included in the membership.',ad:'LaStella Wine Society Benefits',format:'Single image · Meta Ads',sentiment:'negative',priority:'high',time:'27 min ago',unanswered:true,suggestion:'Hi Oliver, thank you for letting us know. The Wine Society includes member access and exclusive wine benefits, with details available on the membership page. We’re also reviewing the page to make the inclusions clearer. If you tell us what you’re looking for, we’ll gladly help.'},
 {id:5,client:'lka',clientName:'LKA Edgemont',person:'Sarah K.',initials:'SK',comment:'We attended last year and my son still talks about it. Highly recommended!',ad:'Fall Skills — Video',format:'Video · Instagram',sentiment:'positive',priority:'low',time:'43 min ago',unanswered:true,suggestion:'Thank you so much, Sarah! We love hearing that your son still remembers the experience. We hope to welcome you both back to the kitchen soon!'},
 {id:6,client:'thrivebox',clientName:'ThriveBox',person:'David L.',initials:'DL',comment:'Can this be shipped as a gift directly to the recipient?',ad:'What Is Inside ThriveBox?',format:'Carousel · Meta Ads',sentiment:'question',priority:'medium',time:'1 hr ago',unanswered:true,suggestion:'Hi David! Great question. We’re confirming the available gift-delivery options for the Winter 2026 box. Please send us a direct message with the destination and we’ll help you with the best option.'},
 {id:7,client:'enotecca',clientName:'Le Vieux Pin',person:'Claire B.',initials:'CB',comment:'Beautiful wines and wonderful service.',ad:'12 Bottles, One Delivery',format:'Carousel · Meta Ads',sentiment:'positive',priority:'low',time:'2 hr ago',unanswered:false,suggestion:'Thank you, Claire! We’re delighted you enjoyed the wines and the experience.'}
];
let selectedId=1,view='all';
const $=id=>document.getElementById(id),esc=s=>s.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));
function filtered(){const q=$('searchInput').value.toLowerCase(),client=$('clientFilter').value,priority=$('priorityFilter').value,sentiment=$('sentimentFilter').value;return comments.filter(c=>(client==='all'||c.client===client)&&(priority==='all'||c.priority===priority)&&(sentiment==='all'||c.sentiment===sentiment)&&(!q||[c.comment,c.ad,c.person,c.clientName].join(' ').toLowerCase().includes(q))&&(view==='all'||view==='unanswered'&&c.unanswered||view==='high'&&c.priority==='high'||view==='resolved'&&!c.unanswered))}
function updateCounts(){const n=comments.filter(c=>c.unanswered).length;$('unansweredCount').textContent=n;$('navBadge').textContent=n;$('tabBadge').textContent=n}
function renderList(){const rows=filtered();$('commentList').innerHTML=rows.length?rows.map(c=>`<article class="comment-row ${c.id===selectedId?'active':''}" data-id="${c.id}"><div class="avatar">${c.initials}</div><div><div class="comment-head"><strong>${esc(c.person)}</strong><span class="client-pill">${esc(c.clientName)}</span>${c.unanswered?'<i class="unread-dot"></i>':''}</div><p class="comment-copy">${esc(c.comment)}</p><div class="comment-meta"><span>${esc(c.ad)}</span><span>·</span><span>${esc(c.format)}</span></div></div><div class="comment-side"><time>${c.time}</time><span class="priority-pill ${c.priority}">${c.priority}</span></div></article>`).join(''):'<div class="empty-list">No comments match these filters.</div>';document.querySelectorAll('.comment-row').forEach(x=>x.onclick=()=>{selectedId=Number(x.dataset.id);renderList();renderDetail()})}
function renderDetail(){const c=comments.find(x=>x.id===selectedId);if(!c){return}$('detailPanel').innerHTML=`<div class="detail-header"><div><h2>${esc(c.person)} <span class="client-pill">${esc(c.clientName)}</span></h2><p>Comment on an active ad · ${c.time}</p></div><div class="detail-actions"><button class="icon-action" title="Snooze">◷</button><button class="icon-action" title="More options">•••</button></div></div><div class="ad-context"><div class="ad-preview ${c.client}"><small>${c.clientName}</small><span>${c.format.split(' · ')[0]}</span></div><div><small>AD CONTEXT</small><strong>${esc(c.ad)}</strong><span>${esc(c.format)} · View ad ↗</span></div></div><div class="conversation"><div class="message"><div class="avatar">${c.initials}</div><div class="bubble"><strong>${esc(c.person)}</strong><p>${esc(c.comment)}</p><small>${c.time}</small></div></div><div class="analysis-tags"><span class="sentiment-pill ${c.sentiment}">${c.sentiment}</span><span class="priority-pill ${c.priority}">${c.priority} priority</span><span class="sentiment-pill question">${c.sentiment==='question'?'FAQ detected':'Human review'}</span></div><div class="ai-box"><header><span>✦ AI-SUGGESTED RESPONSE</span><small>Requires approval</small></header><textarea id="replyText">${esc(c.suggestion)}</textarea><div class="reply-actions"><button class="ghost-button" id="regenerateButton">Regenerate</button><button class="approve-button" id="approveButton">Approve & reply</button></div></div></div>`;$('approveButton').onclick=()=>{c.unanswered=false;updateCounts();renderList();renderDetail();showToast('Reply approved · Prototype only')};$('regenerateButton').onclick=()=>showToast('New response suggestion prepared')}
function showToast(text){$('toast').textContent=text;$('toast').classList.add('show');setTimeout(()=>$('toast').classList.remove('show'),2200)}
document.querySelectorAll('.inbox-tab').forEach(b=>b.onclick=()=>{view=b.dataset.view;document.querySelectorAll('.inbox-tab').forEach(x=>x.classList.toggle('active',x===b));renderList()});['clientFilter','priorityFilter','sentimentFilter'].forEach(id=>$(id).onchange=renderList);$('searchInput').oninput=renderList;$('notificationButton').onclick=()=>showToast('Test notification: New high-priority comment from LKA Fraser');document.querySelectorAll('.switch input').forEach(x=>x.onchange=()=>showToast(x.checked?'Draft rule enabled':'Draft rule paused'));updateCounts();renderList();renderDetail();
